program='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = set()
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            y0=min(y for y,x in cells); x0=min(x for y,x in cells)
            shape=frozenset((y-y0,x-x0) for y,x in cells)
            objects.append({'color':color,'cells':cells,'shape':shape,'box':(y0,x0,max(y for y,x in cells),max(x for y,x in cells))})
    def variants(shape):
        out=set()
        for flip in (1,-1):
            for rot in range(4):
                pts=[]
                for y,x in shape:
                    x*=flip
                    for _ in range(rot): y,x=x,-y
                    pts.append((y,x))
                y0=min(y for y,x in pts); x0=min(x for y,x in pts)
                out.add(frozenset((y-y0,x-x0) for y,x in pts))
        return out
    def embeds(a,b):
        # Can the first object's free polyomino be found in the second?
        bset=b['shape']
        bh=max(y for y,x in bset)+1; bw=max(x for y,x in bset)+1
        for sh in variants(a['shape']):
            shh=max(y for y,x in sh)+1; shw=max(x for y,x in sh)+1
            for dy in range(bh-shh+1):
                for dx in range(bw-shw+1):
                    if all((y+dy,x+dx) in bset for y,x in sh):
                        return True
        return False
    counts=Counter(o['color'] for o in objects)
    candidates=[]
    for i,a in enumerate(objects):
        for j,b in enumerate(objects):
            if i==j or a['color']==b['color']:
                continue
            if embeds(a,b):
                # Prefer the largest matching source; on equal-size copies use the
                # more recurrent color as the reference.
                score=(len(a['cells']), len(b['cells']), counts[b['color']])
                candidates.append((score,a,b))
    if not candidates:
        return [row[:] for row in grid]
    _,src,ref=max(candidates,key=lambda x:x[0])
    out=[row[:] for row in grid]
    for r,c in src['cells']:
        out[r][c]=ref['color']
    return out
'''
